mapper.select:
SELECT dong.code, COUNT(*) FILTER (WHERE place.kind = 'food') AS food, COUNT(*) FILTER (WHERE place.kind = 'cafe') AS cafe, COUNT(*) FILTER (WHERE place.kind IN ('tour', 'culture')) AS tour FROM (VALUES
(#{dong.code}::text, ST_SetSRID(ST_GeomFromGeoJSON(#{dong.geometry}::text), 4326))
) AS dong(code, shape) LEFT JOIN ( SELECT geom::geometry AS point, AS kind FROM retrip_place ) AS place ON ST_Within(place.point, dong.shape) GROUP BY dong.code
